import { useQuery } from '@tanstack/react-query';
import { FixedSizeList as List } from 'react-window';

function UserList() {
  const { data: users = [] } = useQuery({
    queryKey: ['users'],
    queryFn: fetchUsers
  });

  const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => (
    <div style={style} className="flex items-center border-b px-4 py-2">
      <img src={users[index].avatar} className="h-8 w-8 rounded-full" />
      <span className="ml-3">{users[index].name}</span>
    </div>
  );

  return (
    <List
      height={500}
      itemCount={users.length}
      itemSize={50}
      width={"100%"}
    >
      {Row}
    </List>
  );
}

function InfiniteUserList() {
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage
  } = useInfiniteQuery({
    queryKey: ['users', 'infinite'],
    queryFn: ({ pageParam = 0 }) => fetchUsersPage(pageParam),
    getNextPageParam: (lastPage, allPages) => lastPage.nextCursor
  });

  const allUsers = data?.pages.flatMap(page => page.users) ?? [];
  const itemCount = hasNextPage ? allUsers.length + 1 : allUsers.length;

  const Row = ({ index, style }: { index: number; style: React.CSSProperties }) => {
    if (index === allUsers.length) {
      return (
        <div style={style} className="flex justify-center p-4">
          {isFetchingNextPage ? 'Loading...' : 'Load More'}
        </div>
      );
    }
    const user = allUsers[index];
    return (
      <div style={style} className="flex items-center border-b px-4 py-2">
        <img src={user.avatar} className="h-8 w-8 rounded-full" />
        <span className="ml-3">{user.name}</span>
      </div>
    );
  };

  return (
    <List
      height={500}
      itemCount={itemCount}
      itemSize={50}
      width="100%"
      onItemsRendered={({ visibleStopIndex }) => {
        if (visibleStopIndex >= allUsers.length - 5 && hasNextPage) {
          fetchNextPage();
        }
      }}
    >
      {Row}
    </List>
  );
}

